#!/usr/bin/env bash
# Build paper/paper.pdf with Tectonic (a pinned release is downloaded to .tools/ if none is on PATH),
# then the Markdown mirror paper/paper.md and the web reader docs/paper/ with pandoc. Figures and
# tables must already have been generated by `make figures`.
set -euo pipefail
cd "$(dirname "$0")"
ROOT=$(cd .. && pwd)
VERSION=0.16.9
SHA256=60b13a0826ae7ad9ce34b4a2df06bff2cfcfa6dda8a915477c0cbb84e1a4a902
TECTONIC=$(command -v tectonic || true)
if [ -z "$TECTONIC" ]; then
  TECTONIC="$ROOT/.tools/tectonic"
  if [ ! -x "$TECTONIC" ]; then
    mkdir -p "$ROOT/.tools"
    curl -fsSL -o "$ROOT/.tools/tectonic.tar.gz" \
      "https://github.com/tectonic-typesetting/tectonic/releases/download/tectonic%40${VERSION}/tectonic-${VERSION}-x86_64-unknown-linux-musl.tar.gz"
    echo "${SHA256}  $ROOT/.tools/tectonic.tar.gz" | sha256sum -c -
    tar -xzf "$ROOT/.tools/tectonic.tar.gz" -C "$ROOT/.tools"
  fi
fi
"$TECTONIC" --outdir . main.tex
mv main.pdf paper.pdf
if command -v pandoc >/dev/null; then
  python3 md_mirror.py || echo "pandoc mirror failed (PDF is still built)"
  python3 web.py   # docs/paper/, served by mkdocs at /paper/
else
  echo "pandoc not found: paper/paper.md and docs/paper/ not rebuilt"
fi
echo "built $(pwd)/paper.pdf"
